    "You have {0} device at home.": "J\u016bs turite {0} \u012frengin\u012f namuose.", // EN: You have {0} device at home.
    "Right now these are on: {0}.": "\u0160iuo metu \u012fjungti: {0}.", // EN: Right now these are on: {0}.
